describe('File Upload Organization into Folders', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully upload files and organize them into folders', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/upload/files', {
      statusCode: 200,
      body: {
        success: true,
        fileId: '12345',
        folderId: '67890',
        filePath: '/uploads/folder/67890/file_12345.txt'
      }
    }).as('uploadFile');

    // Select file input and upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.txt', { force: true });

    // Verify file upload API was called
    cy.wait('@uploadFile');

    // Verify file appears in the upload list
    cy.get('[data-testid="upload-list"]').should('be.visible');
    cy.get('[data-testid="upload-item-12345"]').should('contain', 'sample.txt');

    // Verify file is organized into the correct folder
    cy.get('[data-testid="upload-item-12345"]').should('have.css', 'background-image', 'url(/uploads/folder/67890/file_12345.png)');

    // Verify file name is displayed
    cy.get('[data-testid="upload-item-12345"]').should('contain', 'sample.txt');

    // Verify file size is displayed
    cy.get('[data-testid="upload-item-12345"]').should('contain', 'Size: 123 KB');

    // Verify file upload button is disabled after successful upload
    cy.get('[data-testid="upload-button"]').should('be.disabled');
  });

  it('should handle uploading files to non-existent folders', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/upload/files', {
      statusCode: 200,
      body: {
        success: false,
        error: 'Folder does not exist'
      }
    }).as('uploadFileError');

    // Select file input and upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.txt', { force: true });

    // Verify file upload API was called
    cy.wait('@uploadFileError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Folder does not exist');

    // Verify file upload button is still enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify file is not listed in the upload list
    cy.get('[data-testid="upload-list"]').should('not.contain', 'sample.txt');
  });
});
